102c3ddb-5c7f-42b3-a001-72248a0189fc.playwright_script:
// Test: Successful Booking
await page.goto('https://adactinhotelapp.com/');
addLog('Navigated to Adactin Hotel App');
addTimelineEvent('Website loaded', 'success');

const username = process.env.TARGET_USERNAME || 'hanish9193';
const password = process.env.TARGET_PASSWORD || 'hanish9193';

await page.fill('#username', username);
await page.fill('#password', password);
await page.click('#login');
await page.waitForURL('**/SearchHotel.aspx', { timeout: 8000 });
addLog('Logged in successfully');

await page.selectOption('#location', 'Sydney');
await page.selectOption('#hotels', 'Hotel Creek');
await page.selectOption('#room_type', 'Standard');
await page.selectOption('#room_nos', '1');
await page.click('#Submit');
await page.waitForURL('**/SelectHotel.aspx', { timeout: 8000 });
addLog('Hotel search submitted');

await page.click('#radiobutton_0');
await page.click('#continue');
await page.waitForURL('**/BookHotel.aspx', { timeout: 8000 });
addLog('Hotel selection confirmed');

await page.fill('#first_name', 'Hanish');
await page.fill('#last_name', 'QA');
await page.fill('#address', '123 QA Lane, Sydney');
await page.fill('#cc_num', '1234567890123456');
await page.selectOption('#cc_type', 'VISA');
await page.selectOption('#cc_exp_month', 'December');
await page.selectOption('#cc_exp_year', '2030');
await page.fill('#cc_cvv', '123');
await page.click('#book_now');
addLog('Booking form submitted');

await page.waitForURL('**/BookingConfirm.aspx', { timeout: 12000 });
const orderNoInput = page.locator('#order_no');
await orderNoInput.waitFor({ state: 'attached', timeout: 5000 });
const orderNo = await orderNoInput.inputValue();

addLog('Booking confirmation successful');
addLog('Generated Order Number: ' + orderNo);
addTimelineEvent('Order Created successfully. Order Number: ' + orderNo, 'success');

