const USERNAME = process.env.TARGET_USERNAME || 'ADACTINFORQA';
const PASSWORD = process.env.TARGET_PASSWORD || 'hanish13';


test('Valid Search with Mandatory Fields', async ({ page }) => {
  const BASE_URL = process.env.TARGET_URL || 'https://adactinhotelapp.com/';
  console.log("[Timeline] Navigate to", BASE_URL);
  await page.goto(BASE_URL);

  // Login
  console.log("[Timeline] Fill username");
  await page.locator('input#username').fill(USERNAME); // NOTE: assuming input ID is correct
  console.log("[Timeline] Fill password");
  await page.locator('input#password').fill(PASSWORD);
  console.log("[Timeline] Click login button");
  const loginButton = page.locator('input#login');
  await loginButton.click();
  // Wait for redirection to complete (e.g., wait for the URL to contain 'SearchHotel.aspx')
  await expect(page).toHaveURL(/SearchHotel\.aspx/);
  // Wait for username show field to be visible
  console.log("[Timeline] Wait for username show field");
  await expect(page.locator('input#username_show')).toBeVisible();

  // Enter 'Melbourne' into the Location dropdown
  console.log("[Timeline] Select location: Melbourne");
  const locationSelector = page.locator('select#location');
  await locationSelector.selectOption({ label: 'Melbourne' });

  // Select '2' from the Number of Rooms dropdown
  console.log("[Timeline] Select number of rooms: 2");
  const roomTypeSelector = page.locator('select#room_type');
  await roomTypeSelector.selectOption({ label: '2 - Two' }); // NOTE: assuming value is correct

  // Enter today's date into the Check In Date field
  console.log("[Timeline] Fill check-in date");
  const todaysDate = new Date();
  const formattedCheckInDate = `${todaysDate.getDate()}/${(todaysDate.getMonth() + 1).toString().padStart(2, '0')}/${todaysDate.getFullYear()}`;
  await page.locator('input#datepick_in').fill(formattedCheckInDate); // NOTE: assuming date format is correct

  // Enter tomorrow's date into the Check Out Date field
  console.log("[Timeline] Fill check-out date");
  const tomorrowsDate = new Date(todaysDate.getTime() + 86400000);
  const formattedCheckOutDate = `${tomorrowsDate.getDate()}/${(tomorrowsDate.getMonth() + 1).toString().padStart(2, '0')}/${tomorrowsDate.getFullYear()}`;
  await page.locator('input#datepick_out').fill(formattedCheckOutDate); // NOTE: assuming date format is correct

  // Click the Search button
  console.log("[Timeline] Click search button");
  const searchButton = page.locator('input#Submit');
  await searchButton.click();

  // Assert that the system navigates to the Select Hotel page showing matching results for Melbourne.
  console.log("[Timeline] Verify select hotel page");
  await expect(page).toHaveURL(/SelectHotel\.aspx/);
});

